section.sourcecode:
========== NOTE: '\' line wrapping per RFC 8792 ==========

{
  "alg": "ES256",
  "backLink": {
    "attestationDigest": "sha256:79acdd4bb3c22a688b1c3321b9a26cafb5c\
  b58c990a963874066d04b8497f70b",
    "attestationNonce": "fixed-attestation-nonce-000"
  },
  "outcomeDerived": {
    "completedAt": "2026-05-29T10:00:00Z",
    "resultCommitment": {
      "projection": "{\"deleted\":true,\"path\":\"/archive/2024-Q3.m\
  d\"}",
      "projectionDigest": "sha256:c9a4caed49b3efaa7908a29a550b8d33ff\
  bb088c52d519242477223a83214198"
    },
    "status": "executed"
  },
  "receiptAsserted": {
    "alg": "ES256",
    "iat": "2026-05-29T10:00:00Z",
    "iss": "issuer://test",
    "nonce": "fixed-receipt-nonce-0001",
    "secretVersion": "v1",
    "sub": "agent:archiver"
  },
  "signature": "867c0439a289d77b75d489b07c42292095c947869365f1c92d98\
  2440338bddf0bb0bf91212cf9b1e681b076315862b5458f5167e98f0fca3a03c42\
  3b2a825f44",
  "version": 1
}

{
  "method": "rfc3161",
  "anchoredDigest": "sha256:...",
  "token": "<base64 DER RFC 3161 TimeStampToken>",
  "authority": "<optional human-readable authority name>"
}

; vaara.receipt/v1 envelope, JSON encoding. ; Maps are closed: a member not named here is not allowed. ; Rules CDDL cannot state are in the prose: runningCount is ; seq + 1, the issuer block alg equals the envelope alg, and ; the classical part of sigSuite equals alg.
receipt = decision-receipt / execution-receipt
decision-receipt = { version: 1, alg: alg, backLink: back-link, decisionDerived: decision-derived, issuerAsserted: issuer-block, signature: hex, ? timestampAnchors: [* anchor], }
execution-receipt = { version: 1, alg: alg, backLink: back-link, outcomeDerived: outcome-derived, receiptAsserted: issuer-block, signature: hex, ? pqSignature: pq-signature, ? existenceProof: existence-proof, }
alg = "ES256" / "RS256" / "HS256" hex = tstr .regexp "[0-9a-f]+" digest = tstr .regexp "sha256:[0-9a-f]{64}" nonempty = tstr .regexp ".+" date-time = tstr .regexp "[0-9-]{10}T[0-9:]{8}([.][0-9]+)?Z" decimal = tstr .regexp "-?[0-9]+([.][0-9]+)?"
back-link = { attestationDigest: digest, attestationNonce: nonempty, ? fallbackProjection: nonempty, }
issuer-block = { iss: tstr, sub: tstr, iat: date-time, nonce: tstr, alg: alg, secretVersion: tstr, ? aud: nonempty, ? taskId: nonempty, ? completeness: completeness, ? sigSuite: "ES256+ML-DSA-65" / "RS256+ML-DSA-65", ? cryptoPosture: crypto-posture, }
completeness = { boundaryId: nonempty, seq: uint, runningCount: uint, }
crypto-posture = { assetType: "algorithm", nistQuantumSecurityLevel: 0..5, algorithms: [+ crypto-algorithm], }
crypto-algorithm = { algorithm: nonempty, primitive: nonempty, nistQuantumSecurityLevel: 0..5, }
decision-derived = { decision: "allow" / "block" / "escalate", decidedAt: date-time, ? reason: tstr, ? policyId: tstr, ? riskScore: decimal, ? thresholdAllow: decimal, ? thresholdBlock: decimal, ? clientTurnId: tstr, ? evidenceRef: evidence-ref, ? rationale: rationale, ? binding: binding, ? decisionProof: { * tstr => any }, }
evidence-ref = { canonicalization: "jcs-rfc8785" / "JCS" / "jcs-json-v1", digest: digest, schema: nonempty, ? ref: nonempty, }
rationale = { rule: tstr, reason: tstr, declaredIntent: tstr, ? intentSatisfied: bool, }
binding = { policyDigest: digest, intentDigest: digest, inputsDigest: digest, bindingDigest: digest, }
outcome-derived = { status: "executed" / "refused" / "errored", completedAt: date-time, ? resultCommitment: projection-commitment / reference-commitment, ? decisionDigest: digest, }
projection-commitment = { projection: tstr, projectionDigest: digest, }
reference-commitment = { ref: tstr, digest: digest, canonicalization: "jcs", }
pq-signature = { alg: "ML-DSA-65", keyid: nonempty, sig: hex, }
existence-proof = { backend: "rfc3161-eidas-qualified", hashAlgorithm: "sha256", recordDigest: digest, token: nonempty, }
anchor = rfc3161-anchor / blinded-anchor / log-anchor / other-anchor
rfc3161-anchor = { method: "rfc3161" / "rfc3161-eidas-qualified", anchoredDigest: digest, token: nonempty, ? authority: tstr, }
blinded-anchor = { method: "rfc3161-blinded" / "rfc3161-eidas-qualified-blinded", anchoredDigest: digest, token: nonempty, anchorSalt: tstr .regexp "[0-9a-f]{64}", ? authority: tstr, }
log-anchor = { method: "scitt", anchoredDigest: digest, logId: nonempty, leafIndex: uint, treeSize: uint, inclusionProof: [* tstr], rootHash: nonempty, ? authority: tstr, }
; A method this document does not define: carried, never ; treated as verified. other-anchor = { method: tstr, anchoredDigest: digest, * tstr => any, }
